import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Lifecycle and registration","description":"","frontmatter":{"navigation":{"category":"Plugin API"},"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/plugin-api/lifecycle-and-registration.md"},"headers":[],"relativePath":"guides/plugin-api/lifecycle-and-registration.md","filePath":"docs/plugin-api/lifecycle-and-registration.md","lastUpdated":1791896572000}`),a={name:`guides/plugin-api/lifecycle-and-registration.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="lifecycle-and-registration" tabindex="-1">Lifecycle and registration <a class="header-anchor" href="#lifecycle-and-registration" aria-label="Permalink to “Lifecycle and registration”">​</a></h1><p>Extend <code>Plugin</code>, provide <code>metadata()</code>, implement <code>onLoad(context)</code> for startup registration, and optionally implement <code>onUnload(context)</code> to save state and release resources. Call <code>registerPlugin(instance)</code> once at module initialization so Pumpkin can invoke the lifecycle exports.</p><p>Event, command, suggestion, AI-goal and chunk-generator callbacks belong to one plugin load. The API releases these callbacks after <code>onUnload</code>, even when it throws, so register them again from a later <code>onLoad</code>.</p><p>If event or command registration with the host fails, the corresponding callback is removed from the dispatch registry before the error is rethrown. A command resource may keep its assigned handler ID if host registration failed after the ID was assigned.</p><p>The facade keeps event, command, suggestion, task, AI-goal and chunk-generator callbacks in handler maps and passes numeric IDs to the host. Register callbacks through the plugin context or <code>Plugin</code> helper methods; do not call the internal <code>handle*</code> dispatch functions from plugin code.</p><p>The default IPC handler rejects messages. Override <code>handleIpcMessage(sender, message)</code> when the plugin accepts IPC. The <a href="/pumpkin-plugins/api/tools/@pumpkin-plugins/pumpkin-api/">generated reference</a> documents the complete facade signatures.</p><p>Scheduled helpers return Pumpkin task IDs. Delayed callbacks are released before they run, including when they throw. Tick counts follow WIT <code>u64</code>: numbers must be safe integers, bigints must be between 0 and 18,446,744,073,709,551,615, and repeating periods must be at least one tick. Repeating callbacks remain registered until cancellation or unload. Call <code>plugin.cancelTask(taskId)</code> to cancel a task created by either helper and release its captured resources; calling the raw scheduler cannot update the facade&#39;s callback registry. Completed and unknown task IDs are ignored. If host cancellation throws, the callback remains registered so the still-active task can continue. Failed scheduling releases the callback immediately. Unload releases all task callbacks even when <code>onUnload</code> throws; Pumpkin disables the plugin&#39;s scheduled tasks. At runtime, tick values must be numbers or bigints; other values are rejected before coercion.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};